export function getArticleBySlug(slug){return articles.find(a=>a.slug===slug);}

export function searchArticles(query='',category=''){const term=query.trim().toLowerCase();let res=articles; if(term){res=res.filter(a=>a.title.toLowerCase().includes(term) || a.summary.toLowerCase().includes(term));} if(category){res=res.filter(a=>a.category===category);} return res;}